import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { getProjects } from '../services/projects';
import { getTasks } from '../services/tasks';
import { Box, Grid, CircularProgress, Alert, Button } from '@mui/material';
import GreetingWidget from '../components/dashboard/GreetingWidget';
import PulseCard from '../components/dashboard/PulseCard';
import ActivityHeatmap from '../components/dashboard/ActivityHeatmap';
import AssignmentIcon from '@mui/icons-material/Assignment';
import FolderIcon from '@mui/icons-material/Folder';
import AccessTimeIcon from '@mui/icons-material/AccessTime';
import TrendingUpIcon from '@mui/icons-material/TrendingUp';
import AddIcon from '@mui/icons-material/Add';
import CreateProjectModal from '../components/projects/CreateProjectModal';

const DashboardPage = () => {
    const [isCreateProjectModalOpen, setIsCreateProjectModalOpen] = useState(false);

    // 1. Fetch Projects
    const {
        data: projects = [],
        isLoading: isLoadingProjects,
        error: projectsError,
        refetch: refetchProjects
    } = useQuery({
        queryKey: ['projects'],
        queryFn: getProjects
    });

    // 2. Fetch Tasks
    const {
        data: tasks = [],
        isLoading: isLoadingTasks
    } = useQuery({
        queryKey: ['allTasks', projects],
        queryFn: async () => {
            if (!projects.length) return [];
            const promises = projects.map((p: any) => getTasks(p.id).catch(() => []));
            const results = await Promise.all(promises);
            return results.flat();
        },
        enabled: projects.length > 0
    });

    const isLoading = isLoadingProjects || (projects.length > 0 && isLoadingTasks);

    const handleProjectCreated = () => {
        refetchProjects();
        // Optionally navigate to the project? Or just refresh list.
    };

    if (isLoading) {
        return (
            <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100vh' }}>
                <CircularProgress />
            </Box>
        );
    }

    if (projectsError) {
        return (
            <Box sx={{ p: 3 }}>
                <Alert severity="error">Failed to load dashboard data. Please try again.</Alert>
            </Box>
        );
    }

    // Calculate Stats
    const totalProjects = projects.length;
    const items = tasks; // all tasks
    const completedTasks = items.filter((t: any) => t.status === 'Completed').length;
    const activeTasksCount = items.filter((t: any) => t.status !== 'Completed').length;
    const pendingReview = items.filter((t: any) => t.status === 'Review').length;

    // Mock calculations
    const teamVelocity = Math.floor(completedTasks * 1.2);

    return (
        <Box sx={{ p: 3, maxWidth: 1600, mx: 'auto' }}>
            <Box sx={{ mb: 4, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <GreetingWidget tasksDueToday={activeTasksCount} />
                <Button
                    variant="contained"
                    startIcon={<AddIcon />}
                    onClick={() => setIsCreateProjectModalOpen(true)}
                    sx={{ height: 'fit-content', py: 1.5 }}
                >
                    New Project
                </Button>
            </Box>

            <Grid container spacing={3} sx={{ mb: 4 }}>
                <Grid item xs={12} sm={6} md={3}>
                    <PulseCard
                        title="Active Projects"
                        value={totalProjects}
                        trend={0}
                        trendLabel="vs last month"
                        icon={<FolderIcon fontSize="large" />}
                        color="primary"
                    />
                </Grid>
                <Grid item xs={12} sm={6} md={3}>
                    <PulseCard
                        title="Completed Tasks"
                        value={completedTasks}
                        trend={10}
                        trendLabel="tasks vs last week"
                        icon={<AssignmentIcon fontSize="large" />}
                        color="success"
                    />
                </Grid>
                <Grid item xs={12} sm={6} md={3}>
                    <PulseCard
                        title="Pending Review"
                        value={pendingReview}
                        trend={-5}
                        trendLabel="in queue"
                        icon={<AccessTimeIcon fontSize="large" />}
                        color="warning"
                    />
                </Grid>
                <Grid item xs={12} sm={6} md={3}>
                    <PulseCard
                        title="Team Velocity"
                        value={teamVelocity}
                        trend={12}
                        trendLabel="vs last week"
                        icon={<TrendingUpIcon fontSize="large" />}
                        color="info"
                    />
                </Grid>
            </Grid>

            {/* Heatmap remains mock for now */}
            <ActivityHeatmap />

            <CreateProjectModal
                open={isCreateProjectModalOpen}
                onClose={() => setIsCreateProjectModalOpen(false)}
                onProjectCreated={handleProjectCreated}
            />
        </Box>
    );
};
export default DashboardPage;

import { useQuery } from '@tanstack/react-query';
import { getProjects } from '../services/projects';
import { Link as RouterLink } from 'react-router-dom';
import {
  Container,
  Typography,
  List,
  ListItem,
  ListItemText,
  Alert,
  CircularProgress,
  Box,
  Button
} from '@mui/material';
import { useState } from 'react';
import CreateProjectModal from '../components/projects/CreateProjectModal';

const ProjectListPage = () => {
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const { data: projects, error, isLoading, refetch } = useQuery({
    queryKey: ['projects'],
    queryFn: getProjects,
  });

  const handleProjectCreated = () => {
    refetch();
  };

  if (isLoading) {
    return (
      <Container>
        <Box sx={{ display: 'flex', justifyContent: 'center', mt: 4 }}>
          <CircularProgress />
        </Box>
      </Container>
    );
  }

  if (error) {
    return (
      <Container>
        <Alert severity="error">Error loading projects: {error.message}</Alert>
      </Container>
    );
  }

  return (
    <Container>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3, mt: 4 }}>
        <Typography variant="h4" component="h2">
          Projects
        </Typography>
        <Button variant="contained" onClick={() => setIsCreateModalOpen(true)}>
          New Project
        </Button>
      </Box>

      {Array.isArray(projects) && projects.length > 0 ? (
        <List>
          {projects.map((project: any) => (
            <ListItem
              key={project.id}
              button
              component={RouterLink}
              to={`/projects/${project.id}`}
            >
              <ListItemText primary={project.name} secondary={project.description} />
            </ListItem>
          ))}
        </List>
      ) : (
        <Box sx={{ textAlign: 'center', mt: 4 }}>
          <Typography gutterBottom>No projects found.</Typography>
          <Button variant="outlined" onClick={() => setIsCreateModalOpen(true)}>Create one now</Button>
        </Box>
      )}

      <CreateProjectModal
        open={isCreateModalOpen}
        onClose={() => setIsCreateModalOpen(false)}
        onProjectCreated={handleProjectCreated}
      />
    </Container>
  );
};

export default ProjectListPage;

import axios from 'axios';
import { getToken } from './auth';

const api = axios.create({
  baseURL: '/api',
});

// Add a request interceptor to include the token in headers
api.interceptors.request.use(
  (config) => {
    const token = getToken();
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

export default api;

import api from './api';

export const getProjects = async () => {
  try {
    const response = await api.get('/projects/');
    return response.data;
  } catch (error) {
    console.error('Failed to fetch projects:', error);
    throw error;
  }
};

export const getProjectById = async (projectId: string) => {
  try {
    const response = await api.get(`/projects/${projectId}`);
    return response.data;
  } catch (error) {
    console.error(`Failed to fetch project ${projectId}:`, error);
    throw error;
  }
};

export const createProject = async (projectData: {
  name: string;
  description?: string;
  start_date?: string;
  end_date?: string;
  status?: string;
}) => {
  try {
    const response = await api.post('/projects/', projectData);
    return response.data;
  } catch (error) {
    console.error('Failed to create project:', error);
    throw error;
  }
};

export const updateProject = async (projectId: string | number, projectData: {
  name?: string;
  description?: string;
  start_date?: string;
  end_date?: string;
  status?: string;
}) => {
  try {
    const response = await api.put(`/projects/${projectId}`, projectData);
    return response.data;
  } catch (error) {
    console.error(`Failed to update project ${projectId}:`, error);
    throw error;
  }
};

export const deleteProject = async (projectId: string | number) => {
  try {
    const response = await api.delete(`/projects/${projectId}`);
    return response.data;
  } catch (error) {
    console.error(`Failed to delete project ${projectId}:`, error);
    throw error;
  }
};

import api from './api';
import { Task } from '../types/task';

// Map frontend Task type to Backend schemas if necessary, for now assuming close enough match
// Backend expects: project_id in query/path, and body for create/update.

export const getTasks = async (projectId: string | number): Promise<Task[]> => {
  const response = await api.get(`/projects/${projectId}/tasks/`);
  // Backend returns list of schemas.Task.
  // We might need to map 'status' to 'columnId' if we want to keep frontend logic isolated, 
  // but better to align frontend to use 'status'.
  // For Kanban, we mapped columnId -> status. 
  // Let's ensure the frontend Task type aligns with backend response.
  return response.data;
};

export const getTask = async (taskId: string | number): Promise<Task> => {
  const response = await api.get(`/tasks/${taskId}`);
  return response.data;
};

export const getTaskById = getTask;

export const createTask = async (projectId: string | number, taskData: Partial<Task>): Promise<Task> => {
  const response = await api.post(`/projects/${projectId}/tasks/`, taskData);
  return response.data;
};

export const updateTask = async (taskId: string | number, taskData: Partial<Task>): Promise<Task> => {
  const response = await api.put(`/tasks/${taskId}`, taskData);
  return response.data;
};

export const deleteTask = async (taskId: string | number): Promise<void> => {
  await api.delete(`/tasks/${taskId}`);
};

import React from 'react';
import { Box, Paper, Typography, Tooltip, useTheme, alpha } from '@mui/material';
import { subDays, format, eachDayOfInterval } from 'date-fns';

const ActivityHeatmap: React.FC = () => {
    const theme = useTheme();

    // Generate mock data for the last 365 days
    const today = new Date();
    const startDate = subDays(today, 364); // Approx 1 year
    const dates = eachDayOfInterval({ start: startDate, end: today });

    const getActivityLevel = (date: Date) => {
        // Mock random activity
        // In real app, map date -> count
        const day = date.getDay();
        const isWeekend = day === 0 || day === 6;
        if (isWeekend) return Math.random() > 0.8 ? Math.floor(Math.random() * 3) : 0;
        return Math.floor(Math.random() * 5);
    };

    const getColor = (level: number) => {
        if (level === 0) return alpha(theme.palette.text.secondary, 0.1);
        if (level === 1) return alpha(theme.palette.primary.main, 0.2);
        if (level === 2) return alpha(theme.palette.primary.main, 0.4);
        if (level === 3) return alpha(theme.palette.primary.main, 0.6);
        return theme.palette.primary.main;
    };

    return (
        <Paper sx={{ p: 3, width: '100%', overflowX: 'auto' }}>
            <Typography variant="h6" fontWeight="600" gutterBottom>
                Contribution Activity
            </Typography>
            <Box sx={{ display: 'flex', gap: 0.5, flexWrap: 'wrap', maxWidth: '100%' }}>
                {dates.map((date) => {
                    const level = getActivityLevel(date);
                    return (
                        <Tooltip key={date.toISOString()} title={`${format(date, 'MMM do')}: ${level} contributions`}>
                            <Box sx={{
                                width: 12,
                                height: 12,
                                borderRadius: '3px',
                                bgcolor: getColor(level),
                                transition: 'all 0.2s',
                                '&:hover': {
                                    transform: 'scale(1.2)',
                                    zIndex: 2
                                }
                            }} />
                        </Tooltip>
                    );
                })}
            </Box>
        </Paper>
    );
};

