import api from './api';

export interface Subtask {
    id: string | number;
    name: string;
    status: string; // 'Not Started' | 'In Progress' | 'Completed'
    parent_task_id: number;
    owner_id: number;
    start_date?: string;
    end_date?: string;
    progress?: number;
    is_completed?: boolean;
    title?: string;
}

export const getSubtasks = async (taskId: string | number): Promise<Subtask[]> => {
    const response = await api.get(`/tasks/${taskId}/subtasks/`);
    return response.data;
};

export const createSubtask = async (taskId: string | number, subtaskData: {
    title: string;
    owner_id: number;
    start_date?: string;
    end_date?: string;
    status?: string;
}): Promise<Subtask> => {
    // Backend requires SubtaskCreate schema: name (mapped from title), owner_id
    const response = await api.post(`/tasks/${taskId}/subtasks/`, {
        name: subtaskData.title, // Backend expects name
        owner_id: subtaskData.owner_id,
        start_date: subtaskData.start_date,
        end_date: subtaskData.end_date,
        status: subtaskData.status
    });
    return response.data;
};

export const updateSubtask = async (subtaskId: string | number, updates: Partial<Subtask>): Promise<Subtask> => {
    const response = await api.put(`/subtasks/${subtaskId}`, updates);
    return response.data;
};

export const deleteSubtask = async (subtaskId: string | number): Promise<void> => {
    await api.delete(`/subtasks/${subtaskId}`);
};

from typing import Annotated

from fastapi import APIRouter, Depends, HTTPException, status
from sqlalchemy.orm import Session

import crud, schemas, models
from database import get_db
from .auth import get_current_active_user

router = APIRouter()

@router.post("/dependencies/", response_model=schemas.Dependency, status_code=status.HTTP_201_CREATED)
def create_dependency(
    dependency: schemas.DependencyCreate,
    db: Annotated[Session, Depends(get_db)],
    current_user: Annotated[models.User, Depends(get_current_active_user)],
):
    # Validate that either prerequisite_id or prerequisite_subtask_id is provided
    if not (dependency.prerequisite_id or dependency.prerequisite_subtask_id):
        raise HTTPException(status_code=400, detail="Either prerequisite_id or prerequisite_subtask_id must be provided")
    if not (dependency.dependent_id or dependency.dependent_subtask_id):
        raise HTTPException(status_code=400, detail="Either dependent_id or dependent_subtask_id must be provided")

    # Validate that the prerequisite exists and current_user has access to it
    if dependency.prerequisite_id:
        prerequisite_task = crud.get_task(db, task_id=dependency.prerequisite_id)
        if prerequisite_task is None:
            raise HTTPException(status_code=404, detail="Prerequisite task not found")
        db_project = crud.get_project(db, project_id=prerequisite_task.project_id)
        if db_project.owner_id != current_user.id:
            # TODO: Check project share permissions
            raise HTTPException(status_code=403, detail="Not authorized to access prerequisite task")
    elif dependency.prerequisite_subtask_id:
        prerequisite_subtask = crud.get_subtask(db, subtask_id=dependency.prerequisite_subtask_id)
        if prerequisite_subtask is None:
            raise HTTPException(status_code=404, detail="Prerequisite subtask not found")
        db_task = crud.get_task(db, task_id=prerequisite_subtask.parent_task_id)
        db_project = crud.get_project(db, project_id=db_task.project_id)
        if db_project.owner_id != current_user.id:
            # TODO: Check project share permissions
            raise HTTPException(status_code=403, detail="Not authorized to access prerequisite subtask")

    # Validate that the dependent exists and current_user has access to it
    if dependency.dependent_id:
        dependent_task = crud.get_task(db, task_id=dependency.dependent_id)
        if dependent_task is None:
            raise HTTPException(status_code=404, detail="Dependent task not found")
        db_project = crud.get_project(db, project_id=dependent_task.project_id)
        if db_project.owner_id != current_user.id:
            # TODO: Check project share permissions
            raise HTTPException(status_code=403, detail="Not authorized to access dependent task")
    elif dependency.dependent_subtask_id:
        dependent_subtask = crud.get_subtask(db, subtask_id=dependency.dependent_subtask_id)
        if dependent_subtask is None:
            raise HTTPException(status_code=404, detail="Dependent subtask not found")
        db_task = crud.get_task(db, task_id=dependent_subtask.parent_task_id)
        db_project = crud.get_project(db, project_id=db_task.project_id)
        if db_project.owner_id != current_user.id:
            # TODO: Check project share permissions
            raise HTTPException(status_code=403, detail="Not authorized to access dependent subtask")

    return crud.create_dependency(db=db, dependency=dependency)

@router.get("/tasks/{task_id}/dependencies/", response_model=list[schemas.Dependency])
def get_task_dependencies(
    task_id: int,
    db: Annotated[Session, Depends(get_db)],
    current_user: Annotated[models.User, Depends(get_current_active_user)],
):
    db_task = crud.get_task(db, task_id=task_id)
    if db_task is None:
        raise HTTPException(status_code=404, detail="Task not found")
    db_project = crud.get_project(db, project_id=db_task.project_id)
    if db_project.owner_id != current_user.id:
        # TODO: Add logic to check project share permissions
        raise HTTPException(status_code=403, detail="Not authorized to view dependencies for this task")
    return crud.get_dependencies_for_task(db=db, task_id=task_id)

@router.get("/subtasks/{subtask_id}/dependencies/", response_model=list[schemas.Dependency])
def get_subtask_dependencies(
    subtask_id: int,
    db: Annotated[Session, Depends(get_db)],
    current_user: Annotated[models.User, Depends(get_current_active_user)],
):
    db_subtask = crud.get_subtask(db, subtask_id=subtask_id)
    if db_subtask is None:
        raise HTTPException(status_code=404, detail="Subtask not found")
    db_task = crud.get_task(db, task_id=db_subtask.parent_task_id)
    db_project = crud.get_project(db, project_id=db_task.project_id)
    if db_project.owner_id != current_user.id:
        # TODO: Add logic to check project share permissions
        raise HTTPException(status_code=403, detail="Not authorized to view dependencies for this subtask")
    return crud.get_dependencies_for_subtask(db=db, subtask_id=subtask_id)

@router.delete("/dependencies/{dependency_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_dependency(
    dependency_id: int,
    db: Annotated[Session, Depends(get_db)],
    current_user: Annotated[models.User, Depends(get_current_active_user)],
):
    db_dependency = crud.get_dependency(db, dependency_id=dependency_id)
    if db_dependency is None:
        raise HTTPException(status_code=404, detail="Dependency not found")

    # Determine the parent project of the dependency and check permissions
    project_id_to_check = None
    if db_dependency.prerequisite_id:
        task = crud.get_task(db, task_id=db_dependency.prerequisite_id)
        if task:
            project_id_to_check = task.project_id
    elif db_dependency.prerequisite_subtask_id:
        subtask = crud.get_subtask(db, subtask_id=db_dependency.prerequisite_subtask_id)
        if subtask:
            task = crud.get_task(db, task_id=subtask.parent_task_id)
            if task:
                project_id_to_check = task.project_id

    if project_id_to_check:
        db_project = crud.get_project(db, project_id=project_id_to_check)
        if db_project is None or db_project.owner_id != current_user.id:
            # TODO: Add logic to check project share permissions
            raise HTTPException(status_code=403, detail="Not authorized to delete this dependency")
    else:
        # If no associated project could be found (shouldn't happen if data integrity is maintained)
        raise HTTPException(status_code=500, detail="Could not determine project for dependency")

    crud.delete_dependency(db=db, dependency_id=dependency_id)
    return

