import React, { createContext, useContext, useState, ReactNode } from 'react';
import CreateProjectModal from '../components/projects/CreateProjectModal';
import { useQueryClient } from '@tanstack/react-query';

interface ProjectCreationContextType {
  isCreateProjectModalOpen: boolean;
  openCreateProjectModal: () => void;
  closeCreateProjectModal: () => void;
  handleProjectCreated: () => void;
}

const ProjectCreationContext = createContext<ProjectCreationContextType | undefined>(undefined);

interface ProjectCreationProviderProps {
  children: ReactNode;
}

export const ProjectCreationProvider: React.FC<ProjectCreationProviderProps> = ({ children }) => {
  const [isCreateProjectModalOpen, setIsCreateProjectModalOpen] = useState(false);
  const queryClient = useQueryClient();

  const openCreateProjectModal = () => setIsCreateProjectModalOpen(true);
  const closeCreateProjectModal = () => setIsCreateProjectModalOpen(false);

  const handleProjectCreated = () => {
    queryClient.invalidateQueries({ queryKey: ['projects'] });
    closeCreateProjectModal();
  };

  return (
    <ProjectCreationContext.Provider
      value={{
        isCreateProjectModalOpen,
        openCreateProjectModal,
        closeCreateProjectModal,
        handleProjectCreated,
      }}
    >
      {children}
      <CreateProjectModal
        open={isCreateProjectModalOpen}
        onClose={closeCreateProjectModal}
        onProjectCreated={handleProjectCreated}
      />
    </ProjectCreationContext.Provider>
  );
};

export const useProjectCreation = () => {
  const context = useContext(ProjectCreationContext);
  if (context === undefined) {
    throw new Error('useProjectCreation must be used within a ProjectCreationProvider');
  }
  return context;
};

