                        title="Team Velocity"
                        value={teamVelocity}
                        trend={12}
                        trendLabel="vs last week"
                        icon={<TrendingUpIcon fontSize="large" />}
                        color="info"
                    />
                </Grid>
            </Grid>

            {/* Recent Tasks Table */}
            <Box sx={{ mb: 4 }}>
                <RecentTasksTable tasks={tasks} />
            </Box>

            <CreateProjectModal
                open={isCreateProjectModalOpen}
                onClose={() => setIsCreateProjectModalOpen(false)}
                onProjectCreated={handleProjectCreated}
            />
        </Box>
    );
};
