const DashboardPage = () => {
    // 1. Fetch Projects
    const {
        data: projects = [],
        isLoading: isLoadingProjects,
        error: projectsError,
        refetch: refetchProjects
    } = useQuery({
        queryKey: ['projects'],
        queryFn: getProjects
    });

    // 2. Fetch Tasks
    const {
        data: tasks = [],
        isLoading: isLoadingTasks
    } = useQuery({
        queryKey: ['allTasks', projects],
        queryFn: async () => {
            if (!projects.length) return [];
            const promises = projects.map((p: any) => getTasks(p.id).catch(() => []));
            const results = await Promise.all(promises);
            return results.flat();
        },
        enabled: projects.length > 0
    });

