                                            <TextField
                                                type="date"
                                                label="Start"
                                                InputLabelProps={{ shrink: true }}
                                                size="small"
                                                fullWidth
                                                value={newSubtaskStart}
                                                onChange={(e) => setNewSubtaskStart(e.target.value)}
                                            />
                                        </Grid>
                                        <Grid item xs={6}>
                                            <TextField
                                                type="date"
                                                label="End"
                                                InputLabelProps={{ shrink: true }}
                                                size="small"
                                                fullWidth
                                                value={newSubtaskEnd}
                                                onChange={(e) => setNewSubtaskEnd(e.target.value)}
                                            />
                                        </Grid>
                                    </Grid>
                                    <Box sx={{ display: 'flex', justifyContent: 'flex-end', gap: 1 }}>
                                        <Button size="small" onClick={() => setIsAddingSubtask(false)}>Cancel</Button>
                                        <Button size="small" variant="contained" onClick={handleAddSubtask}>Add</Button>
                                    </Box>
                                </Box>
                            ) : (
                                <Button startIcon={<AddIcon />} fullWidth variant="outlined" onClick={() => setIsAddingSubtask(true)}>
                                    Add Subtask
                                </Button>
                            )}
                        </Box>

                        <List dense sx={{ bgcolor: 'background.paper', borderRadius: 1 }}>
                            {subtasks.map((sub) => (
                                <ListItem key={sub.id} divider>
                                    <ListItemText
                                        primary={sub.name}
                                        secondary={
                                            sub.start_date || sub.end_date
                                                ? `${sub.start_date?.split('T')[0] || '?'} - ${sub.end_date?.split('T')[0] || '?'}`
                                                : "No dates set"
                                        }
                                    />
                                    <ListItemSecondaryAction>
                                        <IconButton edge="end" size="small" onClick={() => handleDeleteSubtask(sub.id)}>
                                            <DeleteIcon fontSize="small" />
                                        </IconButton>
                                    </ListItemSecondaryAction>
                                </ListItem>
                            ))}
                            {subtasks.length === 0 && <Typography variant="body2" color="text.secondary" align="center">No subtasks yet.</Typography>}
                        </List>
                    </Grid>
                </Grid>
            </DialogContent>
            <DialogActions sx={{ px: 3, pb: 2 }}>
                <Button onClick={onClose} disabled={loading} color="inherit">Cancel</Button>
                <Button
                    onClick={handleSubmit}
                    variant="contained"
                    disabled={loading}
                    sx={{ px: 4 }}
                >
                    Save Changes
                </Button>
            </DialogActions>
        </Dialog>
    );
};

export default EditTaskModal;

import api from './api';

export interface Subtask {
    id: string | number;
    name: string;
    status: string; // 'Not Started' | 'In Progress' | 'Completed'
    parent_task_id: number;
    owner_id: number;
    start_date?: string;
    end_date?: string;
    progress?: number;
    is_completed?: boolean;
    title?: string;
}

export const getSubtasks = async (taskId: string | number): Promise<Subtask[]> => {
    const response = await api.get(`/tasks/${taskId}/subtasks/`);
    return response.data;
};

export const createSubtask = async (taskId: string | number, subtaskData: {
    title: string;
    owner_id: number;
    start_date?: string;
    end_date?: string;
    status?: string;
}): Promise<Subtask> => {
    // Backend requires SubtaskCreate schema: name (mapped from title), owner_id
    const response = await api.post(`/tasks/${taskId}/subtasks/`, {
        name: subtaskData.title, // Backend expects name
        owner_id: subtaskData.owner_id,
        start_date: subtaskData.start_date,
        end_date: subtaskData.end_date,
        status: subtaskData.status
    });
    return response.data;
};

export const updateSubtask = async (subtaskId: string | number, updates: Partial<Subtask>): Promise<Subtask> => {
    const response = await api.put(`/subtasks/${subtaskId}`, updates);
    return response.data;
};

export const deleteSubtask = async (subtaskId: string | number): Promise<void> => {
    await api.delete(`/subtasks/${subtaskId}`);
};

