                        </Box>

                        <List dense sx={{ bgcolor: 'background.paper', borderRadius: 1 }}>
                            {pendingSubtasks.map((sub, index) => (
                                <ListItem key={index} divider>
                                    <ListItemText
                                        primary={sub.name}
                                        secondary={
                                            <React.Fragment>
                                                <Typography component="span" variant="body2" color="text.primary">
                                                    {sub.status} | Progress: {sub.progress}% | Owner: {users.find(u => u.id === sub.owner_id)?.email || 'N/A'}
                                                </Typography>
                                                <br />
                                                {sub.start_date || sub.end_date
                                                    ? <Typography variant="caption">{`${sub.start_date || '?'} - ${sub.end_date || '?'}`}</Typography>
